            pi_binary,
            operator_model,
            operator_system_prompt,
            operator_extension,
            agent_extension_file,
            agent_model,
            agent_thinking,
            remote_cache_dir,
            model_swaps,
            speak_url,
            state_url,
            diagram_url,
            persona,
            env,
